insert into public.ce_course1_resources(id,data) values
('volatile_anesthetics_pdf','{"base64": "", "sha256": "2bdfefdca51bff60b3f8fc4d3e7c75b18b8a16c28c00c5651c80aff4d919368b", "filename": "CE_HALO_Volatile_Anesthetics_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('volatile_anesthetics_questions','[{"module_id": "course_1_module_9", "question_id": "course_1_module_9_q01", "question_number": 1, "stem": "MAC is defined as the alveolar concentration at which what percentage of patients do NOT move in response to a surgical incision?", "choice_a": "50%", "choice_b": "25%", "choice_c": "95%", "choice_d": "75%", "correct_choice": "a", "rationale": "MAC is the alveolar concentration at which 50% of patients do not move in response to a standard surgical incision (Hays, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [1], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q02", "question_number": 2, "stem": "Which of the following statements about MAC and age is MOST accurate?", "choice_a": "MAC increases with age", "choice_b": "MAC decreases with age, so older adults typically require less anesthetic", "choice_c": "MAC only decreases in patients over 90", "choice_d": "MAC is independent of age", "correct_choice": "b", "rationale": "MAC declines progressively with age; older adults generally require less volatile anesthetic than younger adults (Hays, 2025; OpenAnesthesia, 2023).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [1], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q03", "question_number": 3, "stem": "Which inhaled agent has the LOWEST blood-gas partition coefficient (fastest onset/offset) among commonly used volatile liquids?", "choice_a": "Sevoflurane", "choice_b": "Halothane", "choice_c": "Desflurane", "choice_d": "Isoflurane", "correct_choice": "c", "rationale": "Desflurane has the lowest blood-gas solubility among commonly used volatile liquids, supporting rapid adjustment in anesthetic depth (Essackjee & Sebastian, 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [1], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q04", "question_number": 4, "stem": "A CRNA plans an inhalational induction in a 4-year-old. Which volatile agent is MOST appropriate?", "choice_a": "Desflurane, because of its rapid onset", "choice_b": "Isoflurane, because of its low cost", "choice_c": "Halothane, because it is the historic standard", "choice_d": "Sevoflurane, because it is nonpungent and well tolerated with a mask", "correct_choice": "d", "rationale": "Sevoflurane is nonpungent, has smooth mask tolerance, and is the agent of choice for pediatric inhalational induction (Hays, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q05", "question_number": 5, "stem": "Which finding is MOST characteristic of desflurane compared with sevoflurane?", "choice_a": "Pungent airway irritant; may cause tachycardia and hypertension with rapid increases in inspired concentration", "choice_b": "Nonpungent, ideal for mask induction", "choice_c": "High blood-gas solubility", "choice_d": "No environmental impact", "correct_choice": "a", "rationale": "Desflurane is pungent, can irritate the airway, and rapid increases in inspired concentration can provoke sympathetic stimulation (tachycardia, hypertension) (Essackjee & Sebastian, 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q06", "question_number": 6, "stem": "Which of the following is TRUE regarding nitrous oxide potency?", "choice_a": "Its MAC is approximately 1%", "choice_b": "It is a very weak anesthetic (MAC ~104%) but has meaningful analgesic and MAC-sparing properties", "choice_c": "It is equipotent with isoflurane", "choice_d": "It is more potent than sevoflurane", "correct_choice": "b", "rationale": "Nitrous oxide has a MAC of ~104%, making it a weak anesthetic on its own, but it provides analgesia and MAC-sparing effects when combined with volatile agents (Hays, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q07", "question_number": 7, "stem": "A 2024 meta-analysis of 71 RCTs involving 22,147 patients (Kampman et al.) found that adding nitrous oxide to general anesthesia was associated with:", "choice_a": "Reduced postoperative mortality", "choice_b": "No effect on PONV", "choice_c": "Increased PONV without an improvement in major morbidity or mortality", "choice_d": "Reduced overall anesthesia costs", "correct_choice": "c", "rationale": "The 2024 Kampman et al. meta-analysis showed that adding N2O increased PONV (pooled RR 1.27) without improving major postoperative morbidity or mortality (Kampman et al., 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q08", "question_number": 8, "stem": "Which of the following is NOT a triggering agent for malignant hyperthermia?", "choice_a": "Desflurane", "choice_b": "Sevoflurane", "choice_c": "Isoflurane", "choice_d": "Nitrous oxide", "correct_choice": "d", "rationale": "Nitrous oxide is NOT a triggering agent for MH. All potent volatile anesthetics (sevoflurane, desflurane, isoflurane) are triggers (Rosenberg et al., 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q09", "question_number": 9, "stem": "Which sign is often the EARLIEST clinical clue of malignant hyperthermia during a volatile-based anesthetic?", "choice_a": "A rapidly rising end-tidal CO2 out of proportion to ventilation, often with tachycardia and rigidity", "choice_b": "Diffuse rash", "choice_c": "Isolated bradycardia", "choice_d": "High fever", "correct_choice": "a", "rationale": "Rapidly rising ETCO2 (often with tachycardia and rigidity) is one of the earliest MH signs; fever is a late sign (Rosenberg et al., 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q10", "question_number": 10, "stem": "A patient is scheduled for retinal surgery with an intraocular gas bubble. Which inhaled agent should be AVOIDED?", "choice_a": "Sevoflurane", "choice_b": "Nitrous oxide", "choice_c": "Isoflurane", "choice_d": "Desflurane", "correct_choice": "b", "rationale": "Nitrous oxide diffuses into closed gas spaces faster than nitrogen can leave, expanding intraocular gas bubbles and threatening vision (Royal College of Ophthalmologists, 2018).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q11", "question_number": 11, "stem": "A CRNA discontinues nitrous oxide at the end of a case. Which action reduces the risk of diffusion hypoxia?", "choice_a": "Immediately extubate on room air", "choice_b": "Increase the volatile agent to compensate", "choice_c": "Administer supplemental oxygen during and after N2O discontinuation", "choice_d": "Continue N2O until extubation", "correct_choice": "c", "rationale": "Rapid N2O washout can dilute alveolar O2 and CO2 — diffusion hypoxia. Supplemental oxygen during discontinuation is a simple safety step (Abd-Elsayed et al., 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q12", "question_number": 12, "stem": "Which inhaled anesthetic has the LARGEST climate impact per case among commonly used volatile agents?", "choice_a": "Sevoflurane", "choice_b": "Isoflurane", "choice_c": "Xenon", "choice_d": "Desflurane", "correct_choice": "d", "rationale": "Desflurane has a disproportionately high greenhouse-gas footprint compared with other commonly used volatile anesthetics (ASA, 2024; Seibold et al., 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [5], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q13", "question_number": 13, "stem": "In the 2025 Seibold et al. study of desflurane removal, what happened to average CO2-equivalent emissions per patient over the study period?", "choice_a": "Emissions decreased by roughly 80%, with N2O becoming the largest remaining contributor after desflurane elimination", "choice_b": "Emissions were unchanged", "choice_c": "Only pediatric emissions changed", "choice_d": "Emissions increased modestly", "correct_choice": "a", "rationale": "Mean CO2e per patient fell 82.8% (83.1 kg to 14.3 kg) as desflurane was restricted and eliminated; N2O then became the largest remaining contributor (Seibold et al., 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [5], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q14", "question_number": 14, "stem": "Which physiologic effect is characteristic of most modern volatile anesthetics when dose is increased?", "choice_a": "Marked increase in tidal volume", "choice_b": "Dose-dependent decrease in blood pressure, primarily through vasodilation", "choice_c": "No effect on ventilation", "choice_d": "Dose-dependent increase in systemic vascular resistance", "correct_choice": "b", "rationale": "All modern potent volatile agents produce dose-dependent hypotension, primarily via vasodilation and reduced SVR (Hays, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q15", "question_number": 15, "stem": "Which of the following describes the typical respiratory effect of volatile anesthetics?", "choice_a": "Selective stimulation of respiratory rate only", "choice_b": "No effect on respiratory drive", "choice_c": "Dose-dependent ventilatory depression with blunted response to hypercapnia and hypoxia", "choice_d": "Increased tidal volume, enhanced hypercapnic drive", "correct_choice": "c", "rationale": "Volatile anesthetics depress ventilation in a dose-dependent manner, blunt hypercapnic/hypoxic responses, and reduce tidal volume (Hays, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q16", "question_number": 16, "stem": "Which neurologic effect is MOST accurate for volatile anesthetics at higher MAC levels?", "choice_a": "No effect on cerebral hemodynamics", "choice_b": "Reduced cerebral blood flow across all doses", "choice_c": "Consistent decrease in ICP", "choice_d": "Reduced cerebral metabolic rate but increased cerebral blood flow, potentially raising ICP in selected patients", "correct_choice": "d", "rationale": "Volatile agents reduce CMRO2 but can increase CBF at higher MAC, which may increase ICP in vulnerable patients (Hays, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q17", "question_number": 17, "stem": "A pediatric patient has a smooth sevoflurane induction but wakes with agitation, kicking, and inconsolability. This is BEST described as:", "choice_a": "Emergence delirium/agitation, a recognized phenomenon after sevoflurane in children", "choice_b": "Laryngospasm", "choice_c": "Malignant hyperthermia", "choice_d": "Anaphylaxis", "correct_choice": "a", "rationale": "Emergence agitation is recognized after pediatric sevoflurane anesthesia, but first assess pain, hypoxemia, airway obstruction, and other reversible causes.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q18", "question_number": 18, "stem": "Which patient scenario is the STRONGEST indication to avoid nitrous oxide?", "choice_a": "Healthy adult for hernia repair", "choice_b": "Patient with a known pneumothorax scheduled for urgent surgery", "choice_c": "Patient with well-controlled hypertension", "choice_d": "Adolescent for dental extraction", "correct_choice": "b", "rationale": "Nitrous oxide diffuses into closed gas spaces and can expand a pneumothorax; it should be avoided (Hays, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q19", "question_number": 19, "stem": "Which factor is NOT under the CRNA''s direct control when speeding up the onset of an inhaled anesthetic?", "choice_a": "Inspired concentration", "choice_b": "Fresh gas flow", "choice_c": "The blood-gas partition coefficient of the agent", "choice_d": "Alveolar ventilation", "correct_choice": "c", "rationale": "Blood-gas solubility is a fixed property of each agent; inspired concentration, fresh gas flow, and alveolar ventilation are the levers the clinician controls (OpenAnesthesia, 2023).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [1], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q20", "question_number": 20, "stem": "A CRNA plans a case for a hemodynamically fragile 80-year-old. Which titration principle is MOST appropriate?", "choice_a": "Use the same end-tidal concentration as for a healthy 30-year-old", "choice_b": "Avoid all volatile anesthetics", "choice_c": "Rely only on BIS without hemodynamic monitoring", "choice_d": "Use age-adjusted MAC and anticipate greater hypotension and slower recovery", "correct_choice": "d", "rationale": "MAC declines with age; older, frail patients require lower volatile concentrations and are more sensitive to hypotension and delayed recovery (Hays, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [5], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q21", "question_number": 21, "stem": "Which of the following is the MOST accurate statement about low-flow anesthesia?", "choice_a": "It can reduce volatile consumption and greenhouse gas emissions when used safely in stable patients and circuits", "choice_b": "It reliably increases the environmental footprint", "choice_c": "It is contraindicated in all adult cases", "choice_d": "It requires no attention to inspired oxygen concentration", "correct_choice": "a", "rationale": "Low-flow practice requires oxygen and agent monitoring, suitable equipment and absorbents, and an explicit approach to differing sevoflurane labeling and ASA guidance.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [5], "source_ids": [1, 2], "source_urls": ["https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/020478s035lbl.pdf", "https://www.asahq.org/standards-and-practice-parameters/statement-on-the-use-of-low-gas-flows-for-sevoflurane"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q22", "question_number": 22, "stem": "Which of the following BEST describes the relationship between end-tidal monitoring and processed EEG (e.g., BIS)?", "choice_a": "Processed EEG is contraindicated with volatile anesthesia", "choice_b": "End-tidal concentration and processed EEG are complementary; BIS may add value in selected patients but does not replace clinical judgment", "choice_c": "End-tidal monitoring is obsolete", "choice_d": "BIS should replace end-tidal monitoring", "correct_choice": "b", "rationale": "Processed EEG complements — not replaces — end-tidal monitoring and clinical judgment; it may be helpful when awareness risk or excessive depth is a concern (Rabai et al., 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q23", "question_number": 23, "stem": "Which statement about the second gas effect is MOST accurate for modern CRNA practice?", "choice_a": "It has been disproven", "choice_b": "It is the dominant factor determining speed of induction today", "choice_c": "It remains conceptually important but its day-to-day clinical impact is usually modest compared with ventilation, fresh gas flow, and overall technique", "choice_d": "It only applies to isoflurane", "correct_choice": "c", "rationale": "The second gas effect is still relevant to understanding gas kinetics but usually has modest day-to-day clinical impact compared with ventilation and flow (Abd-Elsayed et al., 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [1], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q24", "question_number": 24, "stem": "Which agent is MOST often described as approaching an ''ideal'' inhaled anesthetic profile but is limited by cost and specialized delivery requirements?", "choice_a": "Halothane", "choice_b": "Desflurane", "choice_c": "Isoflurane", "choice_d": "Xenon", "correct_choice": "d", "rationale": "Xenon offers rapid onset/emergence, minimal metabolism, and excellent CV stability but has not been widely adopted due to cost, availability, and the need for closed-circuit delivery systems (Hays, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_9", "question_id": "course_1_module_9_q25", "question_number": 25, "stem": "A CRNA is emerging a patient from a desflurane-based anesthetic. Which statement BEST reflects modern emergence planning?", "choice_a": "A smooth emergence requires attention to pain, airway reactivity, PONV, neuromuscular recovery, and hemodynamics — not just choice of a fast agent", "choice_b": "Coughing at emergence is always benign", "choice_c": "Analgesia should never be given before extubation", "choice_d": "Fast emergence is always equivalent to smooth emergence", "correct_choice": "a", "rationale": "Fast wake-up does not guarantee a smooth wake-up. Emergence quality depends on pain, airway, PONV, NMB recovery, and hemodynamics (Hays, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.asahq.org/about-asa/governance-and-committees/asa-committees/env", "https://doi.org/10.1016/j.mpaic.2024.09.006", "https://www.uptodate.com/contents/inhalation-anesthetic-agents-clinical-effects-and-uses", "https://doi.org/10.1016/j.bja.2024.08.022", "https://www.uptodate.com/contents/emergence-delirium-and-agitation-in-children", "https://www.openanesthesia.org/keywords/inhaled-anesthetic-agents-pharmacodynamics/", "https://www.openanesthesia.org/keywords/eeg-monitoring-and-anesthesia/", "https://www.apsf.org/article/malignant-hyperthermia-moves-out-of-t", "https://www.rcophth.ac.uk/", "https://doi.org/10.1016/j.bja.2025.05.031"], "source_provenance": "provider_submitted_content_and_reference_list"}]'::jsonb)
